/* Numera Academy — Prévias das seções da página inicial.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Visuais das seções ---------- */
function bisectionPreview(){const r=M.bisection(M.parseFunction('x^3-x-2'),1,2,{tolerance:1e-8,maxIterations:60}),rows=r.iterations.filter(t=>Number.isFinite(t.a)).slice(0,6),X=x=>20+(x-1)*340;return `<svg class="mini-svg" viewBox="0 0 400 ${rows.length*30+34}" role="img" aria-label="Intervalos da Bisseção encolhendo em torno da raiz">${rows.map((t,i)=>`<rect class="mini-band" x="${X(t.a).toFixed(1)}" y="${10+i*30}" width="${Math.max(2,X(t.b)-X(t.a)).toFixed(1)}" height="16" rx="8"/><text class="g-label" x="392" y="${23+i*30}" text-anchor="end">passo ${i+1}</text>`).join('')}<path class="g-root-line" d="M${X(r.root).toFixed(1)} 4V${rows.length*30+12}"/><text class="g-label" x="${X(r.root).toFixed(1)}" y="${rows.length*30+28}" text-anchor="middle">raiz ≈ ${short(r.root)}</text></svg>`;}
function gaussPreview(){const {A,b}=M.parseSystem(C.DEEP.gauss.system),r=M.gauss(A,b,{tolerance:1e-8,maxIterations:80}),first=r.iterations[0].matrix,mid=(r.iterations.find((t,i)=>i>0&&t.matrix&&t.matrix.every((row,k)=>row.slice(0,k).every(v=>Math.abs(v)<1e-12)))||r.iterations[r.iterations.length-1]).matrix;const mini=m=>`<table class="mini-matrix"><tbody>${m.map((row,k)=>`<tr>${row.map((v,j)=>`<td class="${j===row.length-1?'rhs':j<k&&Math.abs(v)<1e-12?'zero':''}">${short(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;return `<div class="gauss-preview">${mini(first)}<span class="arrow-big" aria-hidden="true">→</span>${mini(mid)}</div><p class="media-caption">Escalonamento real do motor: zeros abaixo da diagonal, depois retrossubstituição. Solução: ${r.root.map((v,i)=>`x${i+1} = ${short(v)}`).join(', ')}.</p>`;}
function seidelPreview(){const {A,b}=M.parseSystem(C.DEEP.seidel.system),r=M.seidel(A,b,A.map(()=>0),{tolerance:1e-8,maxIterations:80}),rows=r.iterations.filter(t=>Number.isFinite(t.residual)&&t.residual>0).slice(0,9),max=Math.log10(rows[0]?.residual||1),min=Math.min(-9,Math.log10(rows[rows.length-1]?.residual||1e-9));const H=150,W=380,Y=v=>14+(max-Math.log10(v))/(max-min||1)*(H-34);return `<svg class="mini-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Resíduo do Gauss-Seidel caindo a cada iteração">${rows.map((t,i)=>{const x=24+i*((W-48)/Math.max(1,rows.length-1));return `<rect class="mini-bar" x="${(x-10).toFixed(1)}" y="${Y(t.residual).toFixed(1)}" width="20" height="${(H-20-Y(t.residual)).toFixed(1)}" rx="5"/><text class="g-label" x="${x.toFixed(1)}" y="${H-4}" text-anchor="middle">${t.i}</text>`;}).join('')}</svg><p class="media-caption">Resíduo máximo por iteração, em escala logarítmica. Cada coluna é uma iteração real do Gauss-Seidel.</p>`;}
function questionMock(task){return `<div class="mock-q"><span class="tag">Raciocínio</span><p class="mock-title">${safe(task.q)}</p><div class="mock-choices">${task.options.map((o,i)=>`<span class="${i===task.answer?'right':''}"><b>${String.fromCharCode(65+i)}</b>${safe(o)}</span>`).join('')}</div><div class="mock-sheet"><b>Correto!</b> ${safe(task.explain)}</div></div>`;}
function reviewMock(){return `<div class="review-mock">${[['1 dia','Primeira revisão'],['3 dias','Acertou sem ajuda'],['7 dias','Acertou de novo'],['14 dias','Fixado']].map(([d,t],i)=>`<div class="rm-step ${i<2?'done':''}"><b>${d}</b><span>${t}</span></div>`).join('')}</div><p class="media-caption">Errou ou pediu dica? A questão volta no caderno de revisão. Cada acerto sem ajuda afasta a próxima revisão.</p>`;}
function calendarMock(){const days=['S','T','Q','Q','S','S','D'],on=[1,1,0,1,1,1,0];return `<div class="cal-mock">${days.map((d,i)=>`<div class="${on[i]?'on':''}"><span>${d}</span><b>${on[i]?'✓':'·'}</b></div>`).join('')}</div><div class="goal-mock"><span>Objetivo do dia</span><b>3 atividades diferentes</b>${bar(2,3,'Exemplo de objetivo diário')}<small>Exemplo ilustrativo</small></div>`;}
let teaserCache=null;
function teaserScreen(){if(!teaserCache){try{const r=M.smartRoot('x^3 - x - 2 = 0',{tolerance:1e-6,maxIterations:100,min:-40,max:40}),sys=M.parseSystem('2x + y = 5\nx + 3y = 6'),q=M.autoSystem(sys.A,sys.b,sys.A.map(()=>0),{tolerance:1e-6,maxIterations:100});teaserCache={r,q,vars:sys.variables};}catch(_){teaserCache={};}}const {r,q,vars}=teaserCache;if(!r||!q)return '';const n=updates(r);return `<div class="teaser-screen" role="group" aria-label="Exemplo calculado agora pelo motor"><div class="term-line"><span>λ</span> x³ − x − 2 = 0</div><div class="term-out">método escolhido <b>${method(r.method).title}</b></div><div class="term-out">x ≈ <b>${num(r.root)}</b></div><div class="term-out">|f(x)| ≈ ${num(r.residual)} · ${n} ${n===1?'atualização':'atualizações'}</div><div class="term-line dim"><span>λ</span> 2x + y = 5 ; x + 3y = 6</div><div class="term-out">${q.root.map((v,i)=>`${vars?.[i]||'x'+(i+1)} = <b>${num(v)}</b>`).join(' · ')} · ${method(q.method).title}</div></div>`;}

